// The command line that blitz-format and blitz-tidy share: files or stdin in, text out, with --check, --diff and -i.
//
//   tool [options] [file...]      no file or `-`: read stdin, write stdout
//     -i, --in-place              rewrite the files
//         --check                 write the names of files that would change, exit 1 if there are any
//         --diff                  write a unified diff of the changes, exit 1 if there are any
//     -q, --quiet                 no messages except errors
//         --config=FILE           use this configuration file, not the nearest one
//         --no-config             ignore configuration files
//         --stdin-filepath=PATH   the name of stdin for messages and for finding the configuration file
//         --print-config          write the settings that would be used, then exit
//         --KEY=VALUE             a setting; --KEY alone is true and --no-KEY is false
//
// Exit codes: 0 done (and nothing to change with --check/--diff), 1 something would change, 2 an error.
#pragma once
#include <functional>
#include <string>
#include <vector>
#include "config.hpp"

namespace blitz::tools {
	struct driver {
		std::string              name;         // blitz-format
		std::string              version;      // For --version
		std::string              summary;      // One line for --help
		std::vector<std::string> config_names; // Files looked for in every directory: { ".blitz-format", "blitz-format.json" }
		std::string              options_help; // The part of --help that lists the settings

		/** Process one file. Gets the text, the settings from the configuration file overridden by the command line, and the
		 * name of the file: The path as it was given on the command line, the --stdin-filepath value or "<stdin>". Throws
		 * std::runtime_error to refuse a file or a setting (the message is printed, and the exit code is 2).
		 */
		std::function<std::string(std::string const& text, settings const& values, std::string const& name)> process;

		/** Writes the settings as they would be used, for --print-config. Optional.
		 */
		std::function<std::string(settings const& values)> print_config;
	};

	int run(driver const& tool, int argc, char** argv);
} // namespace blitz::tools
